/** A size hierarchy: each node is a leaf carrying a value or a group carrying children, never both. */
export type Data = { name: string; value?: number; children?: Data[] };

type Cell = d3.HierarchyRectangularNode<Data>;

const MARGIN = { top: 8, right: 8, bottom: 8, left: 8 };
const FONT_SIZE = 10;
/** A row shorter than this cannot hold a baseline at y=13 without spilling into its neighbour. */
const MIN_ROW_HEIGHT = 16;
/** Mean advance width of 10px sans-serif, used to drop labels that would overflow their rect. */
const CHAR_WIDTH = 5.6;
const LABEL_INSET = 4;

const formatBytes = d3.format(',d');

function pathOf(node: Cell): string {
  return node
    .ancestors()
    .map((a) => a.data.name)
    .reverse()
    .join('/');
}

/** Every cell takes the colour of the depth-1 package it descends from. */
function packageOf(node: Cell): string {
  let current = node;
  while (current.depth > 1 && current.parent) current = current.parent;
  return current.data.name;
}

export default function Icicle({ data = sourceTree, width }: { data?: Data; width: number }) {
  const height = Math.round(width * 1.15);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const root = useMemo(
    () =>
      d3
        .partition<Data>()
        .size([innerHeight, innerWidth])
        .padding(1)(
          d3
            .hierarchy(data)
            .sum((d) => d.value ?? 0)
            .sort((a, b) => b.height - a.height || (b.value ?? 0) - (a.value ?? 0))
        ),
    [data, innerWidth, innerHeight]
  );

  const color = useMemo(
    () =>
      d3
        .scaleOrdinal<string, string>()
        .domain((data.children ?? []).map((d) => d.name))
        .range(d3.schemeObservable10),
    [data]
  );

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Icicle chart of source file sizes within a nested package hierarchy"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`} fontSize={FONT_SIZE}>
        {root.descendants().map((d) => {
          const cellWidth = d.y1 - d.y0;
          const cellHeight = d.x1 - d.x0;
          const value = formatBytes(d.value ?? 0);
          const room = cellWidth - LABEL_INSET * 2;
          const fitsName = cellHeight > MIN_ROW_HEIGHT && d.data.name.length * CHAR_WIDTH < room;
          const fitsValue = (d.data.name.length + value.length + 1) * CHAR_WIDTH < room;

          return (
            <g key={pathOf(d)} transform={`translate(${d.y0},${d.x0})`}>
              <title>{`${pathOf(d)}\n${value}`}</title>
              <rect
                width={cellWidth}
                height={cellHeight}
                fill={d.depth === 0 ? 'var(--muted)' : color(packageOf(d))}
                fillOpacity={0.6}
              />
              {fitsName && (
                <text x={LABEL_INSET} y={13} fill="var(--text)">
                  {d.data.name}
                  {fitsValue && <tspan fillOpacity={0.7}>{` ${value}`}</tspan>}
                </text>
              )}
            </g>
          );
        })}
      </g>
    </svg>
  );
}
